import { Component } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-weather',
  templateUrl: './weather.component.html',
  styleUrls: ['./weather.component.scss']
})
export class WeatherComponent {
  weatherForm: FormGroup;
  weatherData: any = null;
  loading = false;
  error: string | null = null;

  constructor(private fb: FormBuilder, private http: HttpClient) {
    this.weatherForm = this.fb.group({
      city: ['']
    });
  }

  getWeather() {
    const city = this.weatherForm.value.city;
    if (!city) return;
    this.loading = true;
    this.error = null;
    this.weatherData = null;
  // OpenWeatherMap API key
  const apiKey = 'ffd2f11a144196dd6703770aab793741';
    const url = `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}&units=metric`;
    this.http.get(url).subscribe({
      next: (data) => {
        this.weatherData = data;
        this.loading = false;
      },
      error: (err) => {
        this.error = 'City not found or API error.';
        this.loading = false;
      }
    });
  }
}
<mat-card>
  <mat-card-title>Weather App</mat-card-title>
  <mat-card-content>
    <form [formGroup]="weatherForm" (ngSubmit)="getWeather()">
      <mat-form-field appearance="outline">
        <mat-label>City</mat-label>
        <input matInput formControlName="city" placeholder="Enter city name">
        <button mat-icon-button matSuffix type="submit" [disabled]="loading">
          <mat-icon>search</mat-icon>
        </button>
      </mat-form-field>
    </form>
    <mat-progress-spinner *ngIf="loading" diameter="30"></mat-progress-spinner>
    <mat-error *ngIf="error">{{ error }}</mat-error>
    <div *ngIf="weatherData">
      <h3>{{ weatherData.name }}, {{ weatherData.sys.country }}</h3>
      <p>Temperature: {{ weatherData.main.temp }} °C</p>
      <p>Weather: {{ weatherData.weather[0].description }}</p>
      <mat-chip-listbox>
        <mat-chip color="primary">Humidity: {{ weatherData.main.humidity }}%</mat-chip>
        <mat-chip color="accent">Wind: {{ weatherData.wind.speed }} m/s</mat-chip>
      </mat-chip-listbox>
    </div>
  </mat-card-content>
</mat-card>
